node -e "
const fs=require('fs');
const b=fs.readFileSync('.testivai/baselines/home__desktop/dom.html','utf8');
console.log('baseline dom bytes',b.length);
const t=fs.existsSync('.testivai/temp/home__desktop/dom.html')?fs.readFileSync('.testivai/temp/home__desktop/dom.html','utf8'):null;
console.log('temp dom bytes',t?t.length:null);
"

node -e "
const http=require('http');
const fs=require('fs');
const {chromium}=require('playwright');
(async()=>{
  const srv=http.createServer((req,res)=>{
    let p=req.url.split('?')[0]; if(p==='/')p='/index.html';
    const f='site'+p;
    if(!fs.existsSync(f)){res.writeHead(404);res.end();return;}
    res.writeHead(200,{'content-type':p.endsWith('.css')?'text/css':p.endsWith('.woff2')?'font/woff2':p.endsWith('.html')?'text/html':'application/octet-stream'});
    fs.createReadStream(f).pipe(res);
  }).listen(4199,async()=>{
    const b=await chromium.launch();
    const p=await b.newPage();
    const reqs=[];
    p.on('response',r=>{if(/woff2|css/.test(r.url())) reqs.push([r.status(),r.url(),r.headers()['content-type']])});
    p.on('requestfailed',r=>reqs.push(['FAILED',r.url(),r.failure()]));
    await p.goto('http://127.0.0.1:4199/');
    await p.waitForTimeout(1000);
    const info=await p.evaluate(async()=>{
      await document.fonts.ready;
      const faces=[...document.fonts].map(f=>({family:f.family,weight:f.weight,status:f.status}));
      const c=document.querySelector('h1');
      const cs=getComputedStyle(c);
      return {
        fontsReady:document.fonts.status,
        check400:document.fonts.check('16px \"Acme Sans\"'),
        check700:document.fonts.check('bold 16px \"Acme Sans\"'),
        faces,
        fontFamily:cs.fontFamily,
        fontWeight:cs.fontWeight,
        h1Width:c.getBoundingClientRect().width,
        h1Height:c.getBoundingClientRect().height,
        textMetrics:(()=>{const cv=document.createElement('canvas');const x=cv.getContext('2d');x.font='16px \"Acme Sans\"';const a=x.measureText('Small things');x.font='16px system-ui';const b=x.measureText('Small things');return {acme:a.width,system:b.width};})(),
      };
    });
    console.log(JSON.stringify({info,reqs},null,2));
    await b.close(); srv.close();
  });
})();
"

