node -e "
const http=require('http'),fs=require('fs');
const {chromium}=require('playwright');
(async()=>{
  const srv=http.createServer((req,res)=>{let p=req.url.split('?')[0];if(p==='/')p='/index.html';const f='site'+p;if(!fs.existsSync(f)){res.writeHead(404);res.end();return;}res.writeHead(200,{'content-type':p.endsWith('.css')?'text/css':p.endsWith('.woff2')?'font/woff2':p.endsWith('.html')?'text/html':'application/octet-stream'});fs.createReadStream(f).pipe(res);}).listen(4200,async()=>{
    const b=await chromium.launch();const page=await b.newPage();
    await page.goto('http://127.0.0.1:4200/');await page.evaluate(()=>document.fonts.ready);
    const res=await page.evaluate(async()=>{
      function measure(family,weight,size,text){
        const s=document.createElement('span');
        s.style.cssText='position:absolute;left:-9999px;white-space:nowrap;font-family:'+JSON.stringify(family)+';font-size:'+size+'px;font-weight:'+weight;
        s.textContent=text;document.body.appendChild(s);const w=s.getBoundingClientRect().width;s.remove();return +w.toFixed(2);
      }
      const url=new URL('/fonts/acme-sans.woff2',location.href).href;
      async function addFace(name,desc){const f=new FontFace(name,'url('+url+')',desc);document.fonts.add(f);await f.load();}
      const out={};
      out.current=[measure('Acme Sans',400,18,'Acme Storefront'),measure('Acme Sans',600,18,'Acme Storefront'),measure('Acme Sans',800,18,'Acme Storefront')];
      await addFace('Acme Range',{weight:'100 900'});await addFace('Acme Static400',{weight:'400'});await addFace('Acme Static800',{weight:'800'});await addFace('Acme Static600',{weight:'600'});
      out.range=[measure('Acme Range',400,18,'Acme Storefront'),measure('Acme Range',600,18,'Acme Storefront'),measure('Acme Range',800,18,'Acme Storefront')];
      out.static400=[measure('Acme Static400',800,18,'Acme Storefront')];
      out.static800=[measure('Acme Static800',800,18,'Acme Storefront')];
      out.static600=[measure('Acme Static600',600,18,'Acme Storefront')];
      out.system=[measure('system-ui',800,18,'Acme Storefront')];
      out.navCurrent=[measure('Acme Sans',600,15,'Products'),measure('Acme Sans',400,15,'Products')];
      out.navRange=[measure('Acme Range',600,15,'Products'),measure('Acme Range',400,15,'Products')];
      return out;
    });
    console.log(JSON.stringify(res,null,2));
    await b.close();srv.close();
  });
})();
"

